import{_ as s,o as t,c as o,a0 as r}from"./chunks/framework.DB31oXgM.js";const g=JSON.parse('{"title":"ADR-008: Persistence Strategy (Snapshots, Inputs, Sessions)","description":"","frontmatter":{},"headers":[],"relativePath":"ADR_008_persistence_strategy.md","filePath":"ADR_008_persistence_strategy.md"}'),n={name:"ADR_008_persistence_strategy.md"};function a(i,e,c,l,p,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-008-persistence-strategy-snapshots-inputs-sessions" tabindex="-1">ADR-008: Persistence Strategy (Snapshots, Inputs, Sessions) <a class="header-anchor" href="#adr-008-persistence-strategy-snapshots-inputs-sessions" aria-label="Permalink to &quot;ADR-008: Persistence Strategy (Snapshots, Inputs, Sessions)&quot;">​</a></h1><p><strong>Date:</strong> 2026-10-11<br><strong>Status:</strong> ACCEPTED<br><strong>Context:</strong> C5, E4, E5 — Session recovery, DB schema, backup strategy<br><strong>Decision:</strong> Write-through to Postgres for audit + Redis for low-latency access</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>Persistence requirements:</p><ol><li><strong>Session recovery:</strong> Player disconnects; reconnect token valid 30s; must restore game state</li><li><strong>Audit trail:</strong> Who did what, when; admins need to review bans and incidents</li><li><strong>Snapshots:</strong> Every 100 ticks, store game state snapshot for rollback</li><li><strong>Input history:</strong> All inputs for current match, to resimulate on recovery</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Dual-write model:</p><ul><li><strong>Postgres (authoritative):</strong> Sessions, users, matches, snapshots (compressed with zstd), input history, audit log</li><li><strong>Redis (cache):</strong> Session metadata (player → room mapping), active queue, online presence (TTL 60s)</li></ul><p><strong>Snapshots:</strong> Store every N ticks (100 default); compress with zstd; use binary format (3–5% of uncompressed size)</p><p><strong>Input history:</strong> Store as JSON array in <code>frame_input_logs</code> table; query via <code>match_id</code> + <code>start_tick</code></p><p><strong>Recovery:</strong> On reconnect:</p><ol><li>Load session from Postgres</li><li>Load latest snapshot before disconnect tick</li><li>Replay inputs from snapshot to present</li></ol><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h2><ul><li><strong>Postgres</strong> is permanent; Postgres replication + backups provide durability (PITR)</li><li><strong>Redis</strong> is ephemeral; transient data (online presence) expires automatically</li><li><strong>Compression</strong> reduces storage by 95% for snapshots (500MB uncompressed → 25MB compressed)</li><li><strong>No hot-path writes to Postgres</strong> during active game (async batch writes) reduces latency</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Recovery latency: ~500ms (load snapshot + decompress + replay inputs)</li><li>Storage cost: ~10MB per match (snapshots + input history)</li><li>Replica lag: Eventually consistent; snapshots may be slightly stale on read-replica</li></ul><h2 id="implemented-in-code" tabindex="-1">Implemented In Code <a class="header-anchor" href="#implemented-in-code" aria-label="Permalink to &quot;Implemented In Code&quot;">​</a></h2><p><strong>✅</strong> Schema: <code>backend/migrations/20261010_001_init_schema.sql</code></p><ul><li>Tables: <code>sessions</code>, <code>matches</code>, <code>frame_input_logs</code>, <code>snapshots</code> (pending)</li></ul><p><strong>⏳</strong> Snapshot compression: <code>backend/src/persistence/snapshot.rs::compress_snapshot()</code> — pending C5</p><p><strong>⏳</strong> Recovery logic: <code>backend/src/session/recovery.rs::recover_from_snapshot()</code> — pending C2</p><p><strong>⏳</strong> Async writes: <code>backend/src/persistence/batch_writer.rs</code> — pending E4 optimization</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>C5: Postgres SessionRepository implementation</li><li>E4: DB optimization (indexes, partitioning for input_logs)</li><li>E5: Backup and PITR strategy</li></ul>',24)])])}const u=s(n,[["render",a]]);export{g as __pageData,u as default};
